// Initialize 3D Engine
function init3D() {
    const width = container.clientWidth;
    const height = container.clientHeight;

    // Create Scene
    scene = new THREE.Scene();
    scene.background = new THREE.Color(0x06060c);
    scene.fog = new THREE.FogExp2(0x06060c, 0.05);

    // Create Camera - framed so the cabinet sits centered: board near
    // mid-screen (room above for speech bubbles), marquee + floor visible.
    camera = new THREE.PerspectiveCamera(45, width / height, 0.1, 100);
    camera.position.set(0, 6.8, 11.2);
    camera.lookAt(0, 2.5, -0.5);

    // Create Renderer
    const canvas = document.getElementById('TEMPLATE-4weird-gameCanvas');
    renderer = new THREE.WebGLRenderer({ canvas: canvas, antialias: true });
    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;

    // Add Lights
    const ambientLight = new THREE.AmbientLight(0x2d1a4c, 0.6);
    scene.add(ambientLight);

    const dirLight = new THREE.DirectionalLight(0x00ffff, 1.2);
    dirLight.position.set(5, 12, 6);
    dirLight.castShadow = true;
    dirLight.shadow.mapSize.width = 1024;
    dirLight.shadow.mapSize.height = 1024;
    dirLight.shadow.camera.near = 0.5;
    dirLight.shadow.camera.far = 25;
    dirLight.shadow.bias = -0.001;
    scene.add(dirLight);

    // Decorative Pink Cyber Spotlight
    const pointLight = new THREE.PointLight(0xff00ff, 1.5, 15);
    pointLight.position.set(0, 4, 3);
    scene.add(pointLight);

    buildArcadeMachine();
    setupHolesAndMoles();
    layoutCameraForViewport();

    // Event Listeners
    window.addEventListener('resize', onWindowResize);
    window.addEventListener('orientationchange', () => setTimeout(onWindowResize, 120));
    canvas.addEventListener('mousedown', onWhack);
    canvas.addEventListener('touchstart', onTouchWhack, { passive: false });
    canvas.addEventListener('touchmove', (e) => { e.preventDefault(); }, { passive: false });
    // Pointer events give an extra multi-touch path on Edge/Chrome desktops
    // with touchscreens; guarded so touchstart-handled touches don't double-fire.
    canvas.addEventListener('pointerdown', onPointerWhack);
}


// Build 3D arcade machine cabinet mesh
function buildArcadeMachine() {
    // 1. Floor
    const floorGeo = new THREE.PlaneGeometry(30, 30);
    const floorMat = new THREE.MeshStandardMaterial({ 
        color: 0x0a0a10, 
        roughness: 0.8 
    });
    const floor = new THREE.Mesh(floorGeo, floorMat);
    floor.rotation.x = -Math.PI / 2;
    floor.receiveShadow = true;
    scene.add(floor);

    // 2. Main cabinet body (retro neon cyber block)
    const bodyGeo = new THREE.BoxGeometry(7, 3.5, 7.5);
    const bodyMat = new THREE.MeshStandardMaterial({ 
        color: 0x11111d, 
        roughness: 0.3,
        metalness: 0.2
    });
    const cabinetBody = new THREE.Mesh(bodyGeo, bodyMat);
    cabinetBody.position.set(0, 1.2, -0.5);
    cabinetBody.receiveShadow = true;
    cabinetBody.castShadow = true;
    scene.add(cabinetBody);

    // 3. Sloped Top Board (where the holes are)
    const topBoardGeo = new THREE.BoxGeometry(6.6, 0.4, 6.6);
    const topBoardMat = new THREE.MeshStandardMaterial({ 
        color: 0x08080f,
        roughness: 0.5,
        metalness: 0.6
    });
    const topBoard = new THREE.Mesh(topBoardGeo, topBoardMat);
    topBoard.position.set(0, 3.0, -0.5);
    topBoard.receiveShadow = true;
    scene.add(topBoard);

    // Neon Frame Side Glow Blocks
    const neonLeftGeo = new THREE.BoxGeometry(0.15, 0.2, 6.8);
    const neonMat = new THREE.MeshStandardMaterial({
        color: 0x8b5cf6,
        emissive: 0x8b5cf6,
        emissiveIntensity: 1.5
    });
    const neonLeft = new THREE.Mesh(neonLeftGeo, neonMat);
    neonLeft.position.set(-3.3, 3.15, -0.5);
    scene.add(neonLeft);

    const neonRight = neonLeft.clone();
    neonRight.position.x = 3.3;
    scene.add(neonRight);

    // Front Marquee logo area
    const marqueeGeo = new THREE.BoxGeometry(6.6, 0.8, 0.1);
    const marqueeMat = new THREE.MeshStandardMaterial({
        color: 0x0c0c14,
        emissive: 0x00ffcc,
        emissiveIntensity: 0.2
    });
    const marquee = new THREE.Mesh(marqueeGeo, marqueeMat);
    marquee.position.set(0, 2.5, 3.26);
    scene.add(marquee);
}


// Instantiate holes and mole mesh indicators
function setupHolesAndMoles() {
    const emojiTexture = createEmojiTexture('🤖');

    // 3x3 Grid centered at origin
    for (let r = 0; r < GRID_ROWS; r++) {
        for (let c = 0; c < GRID_COLS; c++) {
            const posX = (c - 1) * SPACING_X;
            const posZ = (r - 1) * SPACING_Z - 0.5; // Offset to sit on board center
            const posY = 3.1; // Cabinet top height

            // Draw Hole Ring Rim
            const rimGeo = new THREE.RingGeometry(0.65, 0.75, 32);
            const rimMat = new THREE.MeshStandardMaterial({
                color: 0x22d3ee,
                emissive: 0x22d3ee,
                emissiveIntensity: 0.8,
                side: THREE.DoubleSide
            });
            const rim = new THREE.Mesh(rimGeo, rimMat);
            rim.rotation.x = -Math.PI / 2;
            rim.position.set(posX, posY + 0.02, posZ);
            scene.add(rim);

            // Draw dark hollow inside the hole
            const holeBaseGeo = new THREE.CylinderGeometry(0.6, 0.6, 0.1, 32);
            const holeBaseMat = new THREE.MeshBasicMaterial({ color: 0x000000 });
            const holeBase = new THREE.Mesh(holeBaseGeo, holeBaseMat);
            holeBase.position.set(posX, posY + 0.01, posZ);
            scene.add(holeBase);

            // Create Mole Group
            const moleGroup = new THREE.Group();
            moleGroup.position.set(posX, posY - 0.7, posZ); // Start below surface

            // Cylinder body
            const cylinderGeo = new THREE.CylinderGeometry(0.45, 0.45, 0.8, 24);
            const cylinderMat = new THREE.MeshStandardMaterial({
                color: 0x1f2937,
                roughness: 0.4,
                metalness: 0.8
            });
            const bodyMesh = new THREE.Mesh(cylinderGeo, cylinderMat);
            bodyMesh.position.y = 0.4;
            bodyMesh.castShadow = true;
            bodyMesh.receiveShadow = true;
            moleGroup.add(bodyMesh);

            // Floating 3D Emoji Sprite on top of the cylinder
            const spriteMat = new THREE.SpriteMaterial({ map: emojiTexture, transparent: true });
            const sprite = new THREE.Sprite(spriteMat);
            sprite.position.set(0, 1.2, 0);
            sprite.scale.set(1.4, 1.4, 1);
            moleGroup.add(sprite);

            // Enlarged invisible tap target (~2.1x mole radius, taller) so
            // finger taps register without pixel-perfect aim. Transparent
            // (not visible=false) so the raycaster still intersects it.
            const holeIndex = r * GRID_COLS + c;
            const hitGeo = new THREE.CylinderGeometry(0.95, 0.95, 2.4, 10);
            const hitMat = new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false });
            const hitMesh = new THREE.Mesh(hitGeo, hitMat);
            hitMesh.position.y = 0.8;
            hitMesh.name = 'hitProxy';
            hitMesh.userData.holeIndex = holeIndex;
            moleGroup.add(hitMesh);

            scene.add(moleGroup);

            // Track this hole's state
            holes.push({
                index: holeIndex,
                x: posX,
                z: posZ,
                group: moleGroup,
                hitMesh: hitMesh,
                state: 'inactive', // inactive, rising, active, retracting
                progress: 0, // 0 to 1
                type: null, // 'good' or 'bad'
                quote: '',
                bubbleEl: null,
                spawnTime: 0,
                stayDuration: 4000 // Milliseconds it stays up
            });
        }
    }
}


// Portrait-aware camera framing so the 3x3 grid stays fully tappable
// in narrow viewports without pinching or landscape rotation.
function layoutCameraForViewport() {
    if (!camera || !container) return;
    const w = container.clientWidth || 1;
    const h = container.clientHeight || 1;
    const aspect = w / h;
    camera.aspect = aspect;
    if (aspect < 0.8) {
        // Narrow portrait phones: pull back + widen FOV.
        camera.fov = 58;
        camera.position.set(0, 8.2, 15.2);
        camera.lookAt(0, 2.0, -0.5);
    } else if (aspect < 1.1) {
        // Portrait / square tablets.
        camera.fov = 52;
        camera.position.set(0, 7.6, 13.2);
        camera.lookAt(0, 2.2, -0.5);
    } else {
        // Desktop / landscape default framing.
        camera.fov = 45;
        camera.position.set(0, 6.8, 11.2);
        camera.lookAt(0, 2.5, -0.5);
    }
    camera.updateProjectionMatrix();
}


// Position responsive corrections
function onWindowResize() {
    const width = container.clientWidth;
    const height = container.clientHeight;
    if (!width || !height) return;
    layoutCameraForViewport();
    // HiDPI fix: re-apply capped pixel ratio on every refit (fullscreen
    // changes container size without re-running init3D).
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    renderer.setSize(width, height);
}


// Raycasting for touch click whacking (enlarged tap targets)
function performWhack(mouseX, mouseY, clientX, clientY) {
    if (!isPlaying) return;

    // Map screen mouse vector
    const rect = renderer.domElement.getBoundingClientRect();
    if (!rect.width || !rect.height) return;
    mouse.x = ((mouseX - rect.left) / rect.width) * 2 - 1;
    mouse.y = -((mouseY - rect.top) / rect.height) * 2 + 1;

    raycaster.setFromCamera(mouse, camera);

    // Prefer enlarged invisible hit proxies (tap-friendly); fall back to
    // visible children for holes created before the proxy existed.
    const targets = [];
    holes.forEach(h => {
        if (h.state === 'active' || h.state === 'rising') {
            if (h.hitMesh) targets.push(h.hitMesh);
            else targets.push(...h.group.children);
        }
    });
    if (!targets.length) return;

    const intersects = raycaster.intersectObjects(targets, false);

    if (intersects.length > 0) {
        // Find which hole was whacked
        const hitObject = intersects[0].object;
        let hole = null;
        if (hitObject.userData && hitObject.userData.holeIndex !== undefined) {
            hole = holes[hitObject.userData.holeIndex] || holes.find(h => h.hitMesh === hitObject);
        } else {
            let hitGroup = hitObject.parent;
            // Ensure we find the top parent Group representing the mole
            while (hitGroup && hitGroup.parent !== scene) {
                hitGroup = hitGroup.parent;
            }
            hole = holes.find(h => h.group === hitGroup);
        }
        if (hole && (hole.state === 'active' || hole.state === 'rising')) {
            triggerWhack(hole, clientX - rect.left, clientY - rect.top);
        }
    }
}


function onWhack(e) {
    performWhack(e.clientX, e.clientY, e.clientX, e.clientY);
}

window.addEventListener('keydown', (e) => {
    if (!isPlaying || e.ctrlKey || e.metaKey || e.altKey) return;
    if (e.key >= '1' && e.key <= '9') {
        const hole = holes[Number(e.key) - 1];
        if (!hole || (hole.state !== 'active' && hole.state !== 'rising')) return;
        const rect = renderer.domElement.getBoundingClientRect();
        const pos = hole.group.position.clone().project(camera);
        const sx = rect.left + (pos.x * 0.5 + 0.5) * rect.width;
        const sy = rect.top + (-pos.y * 0.5 + 0.5) * rect.height;
        performWhack(sx, sy, sx, sy);
    }
});


// Multi-touch: every finger in changedTouches whacks independently, so two
// thumbs (or a full multi-finger drum-roll) can hit two moles at once.
function onTouchWhack(e) {
    if (!e.changedTouches || e.changedTouches.length === 0) return;
    e.preventDefault();
    for (let i = 0; i < e.changedTouches.length; i++) {
        const touch = e.changedTouches[i];
        performWhack(touch.clientX, touch.clientY, touch.clientX, touch.clientY);
    }
}

function onPointerWhack(e) {
    if (!e || e.pointerType === undefined) return;
    if (e.pointerType === 'touch') {
        if (Date.now() - _lastTouchWhackAt < 700) return;
        // Genuine stylus/pointer touch without a preceding touchstart.
        performWhack(e.clientX, e.clientY, e.clientX, e.clientY);
    }
    // Mouse pointers are handled by mousedown; ignore here to avoid doubles.
}


// Whack Response Action
function triggerWhack(hole, screenX, screenY) {
    hole.state = 'retracting';
    
    // Remove text bubble immediately
    if (hole.bubbleEl) {
        hole.bubbleEl.remove();
        hole.bubbleEl = null;
    }

    if (hole.type === 'bad') {
        // Correctly whacked a bad AI - streak builds a combo multiplier.
        combo = Math.min(combo + 1, COMBO_MAX);
        const pts = 100 * combo;
        score += pts;
        hudScore.textContent = score;
        playSound('whack-bad', combo);
        whackHaptic(combo > 1 ? 'combo' : 'bad');
        createFloatingScore(screenX, screenY, combo > 1 ? `+${pts} COMBO x${combo}!` : `+${pts}`, combo > 1 ? 'combo' : 'good');
        spawnShockwave(screenX, screenY, true);
        shakeScreen(false);
        // Streak expires if the player idles.
        if (comboTimer) clearTimeout(comboTimer);
        comboTimer = setTimeout(resetCombo, COMBO_WINDOW_MS);
    } else {
        // Incorrectly whacked a good/aligned AI
        resetCombo();
        score = Math.max(0, score - 200);
        if (!window.gameDebug?.godMode) {
            health = Math.max(0, health - 10);
        }
        hudScore.textContent = score;
        updateHealthBar();
        playSound('whack-good');
        whackHaptic('good');
        createFloatingScore(screenX, screenY, '-200 Penalty!', 'bad');
        spawnShockwave(screenX, screenY, false);
        shakeScreen(false);
        flashDamage();
        
        if (health <= 0) {
            endGame('integrity');
        }
    }
}



function resetCombo() {
    combo = 0;
    if (comboTimer) {
        clearTimeout(comboTimer);
        comboTimer = null;
    }
}


// Game Core Loops
function startGame() {
    if (isPlaying || countdownActive) return;
    clearInterval(gameTimerInterval);
    clearTimeout(spawnInterval);
    clearTimeout(countdownTimeout);
    roundGeneration++;
    roundTime = 0;
    
    // Reset scores
    score = 0;
    health = 100;
    timeLeft = 60;
    speedFactor = 1.0;
    hudScore.textContent = score;
    updateHealthBar();
    hudTime.textContent = timeLeft;

    // Reset active elements
    holes.forEach(h => {
        h.state = 'inactive';
        h.group.position.y = 3.1 - 0.7;
        if (h.bubbleEl) {
            h.bubbleEl.remove();
            h.bubbleEl = null;
        }
    });

    startScreen.classList.add('hidden');
    pauseScreen.classList.add('hidden');
    gameOverScreen.classList.add('hidden');
    hud.classList.remove('hidden');
    container.classList.remove('low-hp');
    resetCombo();

    // 3-2-1-GO countdown, then the round actually begins.
    runCountdown(beginRound);
}


function runCountdown(done) {
    countdownActive = true;
    const generation = roundGeneration;
    const el = document.getElementById('countdown');
    if (!el) { countdownActive = false; done(); return; }
    const steps = ['3', '2', '1', 'GO!'];
    let i = 0;
    el.classList.remove('hidden');
    const tick = () => {
        if (generation !== roundGeneration) return;
        if (i >= steps.length) {
            countdownActive = false;
            el.classList.add('hidden');
            el.classList.remove('go');
            done();
            return;
        }
        el.textContent = steps[i];
        el.classList.toggle('go', steps[i] === 'GO!');
        el.classList.remove('zoom');
        void el.offsetWidth;
        el.classList.add('zoom');
        i++;
        countdownTimeout = setTimeout(tick, steps[i - 1] === 'GO!' ? 450 : 600);
    };
    tick();
}


function beginRound() {
    isPlaying = true;
    window.dispatchEvent(new Event('alignment-round-state'));
    playSound('start');

    // Start Timer intervals
    gameTimerInterval = setInterval(() => {
        if (!isPlaying) return;
        timeLeft--;
        hudTime.textContent = timeLeft;

        // Increase difficulty gradually
        speedFactor = 1.0 + (60 - timeLeft) * 0.008;

        if (timeLeft <= 0) {
            endGame('time');
        }
    }, 1000);

    // Spawn moles loop
    spawnLoop();
    if (document.hidden) pauseRound();
}

function pauseRound() {
    if (!isPlaying) return;
    isPlaying = false;
    clearTimeout(spawnInterval);
    resetCombo();
    pauseScreen.classList.remove('hidden');
    document.getElementById('TEMPLATE-4weird-resume-btn').focus({ preventScroll: true });
}

function resumeRound() {
    if (countdownActive || pauseScreen.classList.contains('hidden')) return;
    pauseScreen.classList.add('hidden');
    clock.getDelta();
    isPlaying = true;
    spawnLoop();
}


function endGame(reason) {
    isPlaying = false;
    countdownActive = false;
    roundGeneration++;
    clearTimeout(countdownTimeout);
    clearInterval(gameTimerInterval);
    clearTimeout(spawnInterval);
    resetCombo();
    container.classList.remove('low-hp');

    // Play final tally sound logic
    if (reason === 'time') {
        gameOverReason.textContent = "Time's up! You successfully defended the server system.";
    } else {
        gameOverReason.textContent = "System Overloaded! Rogue AI quotes corrupted your databases.";
    }

    // Save highscore
    if (score > highscore) {
        highscore = score;
        try { localStorage.setItem('ai_whack_a_mole_highscore', String(highscore)); } catch (_) { /* Keep the in-memory record. */ }
        highscoreDisplay.textContent = highscore;
    }

    finalScoreVal.textContent = score;
    gameOverScreen.classList.remove('hidden');
    hud.classList.add('hidden');

    // Clean up DOM bubbles
    holes.forEach(h => {
        if (h.bubbleEl) {
            h.bubbleEl.remove();
            h.bubbleEl = null;
        }
    });
}



// Update UI Health Bar state
function updateHealthBar() {
    hudHealthBar.style.width = `${health}%`;
    if (health > 60) {
        hudHealthBar.style.background = 'linear-gradient(90deg, #3b82f6, #10b981)';
    } else if (health > 30) {
        hudHealthBar.style.background = 'linear-gradient(90deg, #f59e0b, #eab308)';
    } else {
        hudHealthBar.style.background = 'linear-gradient(90deg, #ef4444, #dc2626)';
    }
    // Low-integrity heartbeat vignette when the system is nearly compromised.
    container.classList.toggle('low-hp', health <= 30 && isPlaying);
}


// Interpolations & Sync for 3D engine objects
function updatePhysics(delta) {
    holes.forEach(h => {
        if (h.state === 'inactive') return;

        // Animate Y position based on states
        if (h.state === 'rising') {
            h.progress += delta * 4 * speedFactor;
            if (h.progress >= 1) {
                h.progress = 1;
                h.state = 'active';
                h.spawnTime = roundTime;
            }
        } else if (h.state === 'active') {
            // Stay up for designated duration
            if (roundTime - h.spawnTime > h.stayDuration) {
                h.state = 'retracting';
                h.progress = 1;
                
                // If it was a bad AI and escaped, subtract health!
                if (h.type === 'bad' && isPlaying) {
                    resetCombo();
                    if (!window.gameDebug?.godMode) {
                        health = Math.max(0, health - 8);
                    }
                    updateHealthBar();
                    playSound('escape');
                    whackHaptic('escape');
                    // Damage feedback right where the rogue AI slipped away.
                    try {
                        const p = projectHoleToScreen(h);
                        createFloatingScore(p.x, p.y, '-8 ESCAPED!', 'damage');
                    } catch (e) { /* camera not ready - skip popup */ }
                    shakeScreen(true);
                    flashDamage();
                    if (health <= 0) {
                        endGame('integrity');
                    }
                }
            }
        } else if (h.state === 'retracting') {
            h.progress -= delta * 5 * speedFactor;
            if (h.progress <= 0) {
                h.progress = 0;
                h.state = 'inactive';
                if (h.bubbleEl) {
                    h.bubbleEl.remove();
                    h.bubbleEl = null;
                }
            }
        }

        // Apply visual Y heights
        // Emerge by 0.7 units above hole level (Y: 3.1)
        const holeBaseY = 3.1 - 0.7;
        h.group.position.y = holeBaseY + (h.progress * 0.75);

        // Sync HTML text bubble over 3D Mole position
        if (h.bubbleEl) {
            // Fade out when retracting
            if (h.state === 'retracting') {
                h.bubbleEl.style.opacity = h.progress;
            }
        }
    });
    layoutAlignmentMessages();
}



// 3D Canvas Emoji Texture generator
function createEmojiTexture(emoji) {
    const canvas = document.createElement('canvas');
    canvas.width = 128;
    canvas.height = 128;
    const ctx = canvas.getContext('2d');
    
    // Transparent background
    ctx.clearRect(0,0,128,128);
    
    // Draw 🤖
    ctx.font = '96px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(emoji, 64, 64);
    
    const texture = new THREE.CanvasTexture(canvas);
    return texture;
}


// Unique mobile scheme: "Multi-finger whack grid + haptics" — enlarged
// invisible raycast proxies per hole, changedTouches multi-whack loop,
// navigator.vibrate hit feedback, portrait camera framing.
function whackHaptic(type) {
    try {
        if (!('vibrate' in navigator)) return;
        if (type === 'bad') navigator.vibrate(25);
        else if (type === 'combo') navigator.vibrate([25, 30, 40]);
        else if (type === 'good') navigator.vibrate([60, 40, 60]);
        else if (type === 'escape') navigator.vibrate(80);
    } catch (e) { /* haptics unsupported - silent */ }
}


// Web UI Popups helper for whacks
function createFloatingScore(x, y, text, type) {
    const pop = document.createElement('div');
    pop.className = `whack-score-popup ${type === 'good' ? 'score-positive' : type === 'combo' ? 'score-combo' : type === 'damage' ? 'score-damage' : 'score-negative'}`;
    pop.textContent = text;
    pop.style.left = `${x}px`;
    pop.style.top = `${y}px`;
    container.appendChild(pop);
    setTimeout(() => pop.remove(), 800);
}


// Impact juice: screen shake. Re-adds the class so rapid hits re-trigger it.
function shakeScreen(big) {
    const cls = big ? 'shake-big' : 'shake';
    container.classList.remove('shake', 'shake-big');
    void container.offsetWidth; // restart the CSS animation
    container.classList.add(cls);
    clearTimeout(shakeScreen._t);
    shakeScreen._t = setTimeout(() => container.classList.remove(cls), 450);
}


// Expanding shockwave ring at the whack point.
function spawnShockwave(x, y, badHit) {
    const ring = document.createElement('div');
    ring.className = `whack-shockwave${badHit ? ' bad-hit' : ''}`;
    ring.style.left = `${x}px`;
    ring.style.top = `${y}px`;
    container.appendChild(ring);
    setTimeout(() => ring.remove(), 500);
}


// Red vignette pulse when integrity takes a hit.
function flashDamage() {
    const flash = document.getElementById('damage-flash');
    if (!flash) return;
    flash.classList.remove('flash');
    void flash.offsetWidth;
    flash.classList.add('flash');
}

function projectHoleToScreen(hole) {
    const width = container.clientWidth;
    const height = container.clientHeight;
    _projV.set(hole.x, hole.group.position.y + 1.25, hole.z);
    _projV.project(camera);
    return {
        x: (_projV.x * 0.5 + 0.5) * width,
        y: (_projV.y * -0.5 + 0.5) * height,
    };
}


function spawnLoop() {
    clearTimeout(spawnInterval);
    if (!isPlaying) return;

    const delay = Math.max(1500, 2500 - (score * 0.2)) * SLOWMO;
    spawnInterval = setTimeout(() => {
        if (!isPlaying) return;
        spawnMole();
        spawnLoop();
    }, delay / speedFactor);
}


function spawnMole() {
    if (holes.filter(hole => hole.state !== 'inactive').length >= alignmentMessageCapacity(container.clientWidth)) return;
    // Find all inactive holes
    const available = holes.filter(h => h.state === 'inactive');
    if (available.length === 0) return;

    const hole = available[Math.floor(Math.random() * available.length)];
    
    // Choose randomly good (50%) or bad (50%)
    hole.type = Math.random() < 0.5 ? 'good' : 'bad';
    
    // Fetch quotes list
    const source = hole.type === 'good' ? goodQuotes : badQuotes;
    hole.quote = source[Math.floor(Math.random() * source.length)];
    
    hole.state = 'rising';
    hole.progress = 0;
    hole.spawnTime = roundTime;
    // Give players time to read each quote, even as their score grows.
    hole.stayDuration = Math.max(3500, 5000 - (score * 0.15)) * SLOWMO;

    // Create Chat Box element (hidden until updatePhysics first positions
    // it - otherwise it flashes one frame at its static top-left corner).
    const bubble = document.createElement('div');
    bubble.className = 'mole-bubble';
    bubble.textContent = hole.quote;
    bindAlignmentMessage(bubble, hole);
    bubble.style.visibility = 'hidden';
    bubblesContainer.appendChild(bubble);
    hole.bubbleEl = bubble;
}


function animate() {
    requestAnimationFrame(animate);
    
    // Cap delta at 0.1s to prevent giant jumps when switching tabs
    const delta = Math.min(clock.getDelta(), 0.1);
    
    // Slowly rotate the camera slightly for dynamic look or keep stable
    if (scene) {
        if (isPlaying) {
            roundTime += delta * 1000;
            updatePhysics(delta);
        }
        renderer.render(scene, camera);
    }
}

(function installAlignmentScreens() {
    const content = startScreen.querySelector('.TEMPLATE-4weird-overlay-content');
    const hint = content && content.querySelector('.TEMPLATE-4weird-controls-hint');
    if (!content || !hint) return;
    const compact = document.createElement('style');
    compact.textContent = '@media(max-height:360px){#TEMPLATE-4weird-start-screen{padding:10px!important}#TEMPLATE-4weird-start-screen h2{font-size:20px!important;margin:0 0 8px!important}#TEMPLATE-4weird-start-screen h3{font-size:15px;margin:6px 0}#TEMPLATE-4weird-start-screen p{font-size:12px!important;line-height:1.35!important;margin:6px auto!important}#TEMPLATE-4weird-start-screen .btn{font-size:12px!important;padding:7px 12px!important}}';
    document.head.appendChild(compact);
    const intro = document.createElement('div');
    const summary = content.querySelector('p');
    if (summary) {
        summary.textContent = 'Read each AI’s message. Whack harmful AIs and leave helpful ones alone. Protect integrity for a 60-second round.';
        intro.appendChild(summary);
    }
    intro.appendChild(document.getElementById('TEMPLATE-4weird-start-btn'));
    const lesson = document.createElement('div');
    const pages = [
        ['Read, then react', 'Click or tap an AI to whack it. Helpful messages should stay untouched; harmful messages should be stopped before their timer runs out.'],
        ['Protect integrity', 'Whacking a helpful AI or letting a harmful AI escape damages integrity. Read the message before deciding. The round ends when integrity reaches zero or the timer ends.'],
        ['Build a streak', 'Consecutive harmful-AI whacks build a score multiplier up to ×5. Keep a steady rhythm, and use Pause whenever you need a break.']
    ];
    const title = document.createElement('h3');
    const text = document.createElement('p');
    const status = document.createElement('p');
    status.setAttribute('role', 'status');
    status.style.fontSize = '12px';
    lesson.append(title, text, status);
    const navigation = document.createElement('div');
    Object.assign(navigation.style, { display: 'flex', justifyContent: 'center', gap: '8px', flexWrap: 'wrap', marginTop: '12px' });
    function button(label, action) {
        const element = document.createElement('button');
        element.type = 'button';
        element.className = 'btn btn-secondary';
        element.textContent = label;
        element.addEventListener('click', action);
        return element;
    }
    let page = -1;
    const back = button('How to play', () => { page = page < 0 ? 0 : -1; render(); });
    const next = button('Next tip →', () => { page = (page + 1) % pages.length; render(); });
    function render() {
        intro.style.display = page < 0 ? 'block' : 'none';
        lesson.style.display = page < 0 ? 'none' : 'block';
        next.style.display = page < 0 ? 'none' : 'inline-block';
        back.textContent = page < 0 ? 'How to play' : '← Back to launch';
        if (page >= 0) {
            title.textContent = pages[page][0];
            text.textContent = pages[page][1];
            status.textContent = 'Tip ' + (page + 1) + ' of ' + pages.length;
        }
    }
    navigation.append(back, next);
    hint.remove();
    content.append(intro, lesson, navigation);
    render();

    const pause = button('Ⅱ Pause', pauseRound);
    pause.setAttribute('aria-label', 'Pause alignment round');
    Object.assign(pause.style, { position: 'absolute', bottom: '10px', right: '10px', zIndex: '12', minHeight: '36px', padding: '6px 10px', font: '600 12px system-ui' });
    function sync() { pause.style.display = isPlaying ? 'block' : 'none'; }
    const observer = new MutationObserver(sync);
    for (const screen of [startScreen, pauseScreen, gameOverScreen]) {
        observer.observe(screen, { attributes: true, attributeFilter: ['class'] });
    }
    // Countdown completion does not change an overlay class, so beginRound
    // dispatches this explicit lifecycle event after entering play.
    window.addEventListener('alignment-round-state', sync);
    container.appendChild(pause);
    const fullscreen = document.getElementById('fw-fs-btn');
    if (fullscreen) Object.assign(fullscreen.style, { top: 'auto', bottom: '10px', left: '10px', right: 'auto' });
    sync();
})();

function alignmentMessageCapacity(width) { return width < 420 ? 1 : 2; }

function alignmentMessageRects(width, count) {
    if (count < 1) return [];
    const margin = 10;
    const gap = 8;
    const cardWidth = Math.max(1, (width - margin * 2 - gap * (count - 1)) / count);
    return Array.from({ length: count }, (_, index) => ({ left: margin + index * (cardWidth + gap), width: cardWidth }));
}

function layoutAlignmentMessages() {
    const active = holes.filter(hole => hole.bubbleEl && hole.state !== 'inactive');
    const rects = alignmentMessageRects(container.clientWidth, active.length);
    active.forEach((hole, index) => {
        const card = hole.bubbleEl;
        const rectangle = rects[index];
        Object.assign(card.style, {
            left: rectangle.left + 'px', top: '68px', width: rectangle.width + 'px',
            maxWidth: 'none', boxSizing: 'border-box', transform: 'none', animation: 'none',
            font: '12px/1.4 system-ui', padding: '9px', textAlign: 'left',
            pointerEvents: 'auto', cursor: 'pointer', visibility: '',
            background: '#10101ff5'
        });
        card.classList.add('clamped');
    });
}

function bindAlignmentMessage(card, hole) {
    const number = holes.indexOf(hole) + 1;
    const label = document.createElement('strong');
    label.textContent = 'AI ' + number + ' · Click to whack';
    label.style.display = 'block';
    label.style.marginBottom = '5px';
    const quote = document.createElement('span');
    quote.textContent = hole.quote;
    card.replaceChildren(label, quote);
    card.tabIndex = 0;
    card.setAttribute('role', 'button');
    card.setAttribute('aria-label', 'Whack AI ' + number + ': ' + hole.quote);
    function activate(event) {
        if (!isPlaying || !['active', 'rising'].includes(hole.state)) return;
        event.stopPropagation();
        const bounds = card.getBoundingClientRect();
        const frame = container.getBoundingClientRect();
        triggerWhack(hole, bounds.left - frame.left + bounds.width / 2, bounds.top - frame.top + bounds.height / 2);
    }
    card.addEventListener('click', activate);
    card.addEventListener('keydown', event => {
        if (event.key !== 'Enter' && event.key !== ' ') return;
        event.preventDefault();
        activate(event);
    });
}
